// GENERATED by bundle.mjs from logic.ts, handler.ts and index.ts. Edit those, then rebuild.

// Paste this whole file into Supabase > Edge Functions > lemon-webhook > Code, and keep "Verify JWT" OFF.

// Pure webhook logic for Lemon Squeezy subscription events. No Deno or Node APIs beyond Web Crypto, so it runs in both.

type Plan = "free" | "monthly" | "sixmonth" | "yearly";
type Mode = "test" | "live" | "both";
interface Config { variants: Record<string, Plan>; products: Record<string, Plan>; mode: Mode }
interface Applied {
  kind: "apply"; plan: Plan; userId: string | null; email: string | null;
  subscriptionId: string | null; eventTime: string; eventKey: string; eventName: string; test: boolean;
}
interface Ignored { kind: "ignore"; reason: string }
type Decision = Applied | Ignored;

const enc = new TextEncoder();
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
// Events that change what a person is entitled to. Everything else is acknowledged and ignored.
const HANDLED = new Set([
  "subscription_created", "subscription_updated", "subscription_resumed", "subscription_unpaused",
  "subscription_cancelled", "subscription_paused", "subscription_expired",
]);

function parseConfig(env: Record<string, string | undefined>): Config {
  // Plans are matched by variant id or, more simply, by product id (one product per plan). Either works.
  const variants: Record<string, Plan> = {}, products: Record<string, Plan> = {};
  const add = (to: Record<string, Plan>, id: string | undefined, plan: Plan) => { if (id && id.trim()) to[id.trim()] = plan; };
  add(variants, env.LS_VARIANT_MONTHLY, "monthly");
  add(variants, env.LS_VARIANT_SIXMONTH, "sixmonth");
  add(variants, env.LS_VARIANT_YEARLY, "yearly");
  add(products, env.LS_PRODUCT_MONTHLY, "monthly");
  add(products, env.LS_PRODUCT_SIXMONTH, "sixmonth");
  add(products, env.LS_PRODUCT_YEARLY, "yearly");
  const m = (env.LS_MODE || "live").toLowerCase();
  return { variants, products, mode: m === "test" || m === "both" ? (m as Mode) : "live" };
}

function hexToBytes(hex: string): Uint8Array | null {
  if (!/^[0-9a-f]+$/i.test(hex) || hex.length % 2) return null;
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  return out;
}

// Lemon Squeezy sends hex(HMAC-SHA256(raw body, signing secret)) in the X-Signature header.
async function verifySignature(raw: string, signature: string | null, secret: string): Promise<boolean> {
  if (!signature || !secret) return false;
  const sig = hexToBytes(signature.trim());
  if (!sig) return false;
  const key = await crypto.subtle.importKey("raw", enc.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["verify"]);
  return crypto.subtle.verify("HMAC", key, sig, enc.encode(raw)); // constant-time compare
}

async function sha256Hex(s: string): Promise<string> {
  const d = new Uint8Array(await crypto.subtle.digest("SHA-256", enc.encode(s)));
  return [...d].map((b) => b.toString(16).padStart(2, "0")).join("");
}

async function decide(body: any, cfg: Config, now: number = Date.now()): Promise<Decision> {
  const name: string | undefined = body?.meta?.event_name;
  if (!name) return { kind: "ignore", reason: "no event name" };
  const test = !!body?.meta?.test_mode;
  if (test && cfg.mode === "live") return { kind: "ignore", reason: "test event while LS_MODE=live" };
  if (!test && cfg.mode === "test") return { kind: "ignore", reason: "live event while LS_MODE=test" };
  if (!HANDLED.has(name)) return { kind: "ignore", reason: `event ${name} is not used` };

  const attrs = body?.data?.attributes;
  const id = body?.data?.id;
  if (!attrs || id == null) return { kind: "ignore", reason: "no subscription data" };
  const planOfVariant = cfg.variants[String(attrs.variant_id)] || cfg.products[String(attrs.product_id)];
  if (!planOfVariant) return { kind: "ignore", reason: `unknown product ${attrs.product_id} / variant ${attrs.variant_id}` };
  const updated: string | undefined = attrs.updated_at;
  if (!updated || Number.isNaN(Date.parse(updated))) return { kind: "ignore", reason: "no updated_at" };

  // Who still gets access. A cancelled subscription keeps access until the period it paid for ends.
  const status: string = String(attrs.status || "");
  let plan: Plan;
  if (name === "subscription_expired" || name === "subscription_paused" || ["expired", "paused", "unpaid"].includes(status)) plan = "free";
  else if (status === "cancelled") {
    const ends = attrs.ends_at ? Date.parse(attrs.ends_at) : NaN;
    plan = !Number.isNaN(ends) && ends <= now ? "free" : planOfVariant;
  } else if (["active", "on_trial", "past_due"].includes(status)) plan = planOfVariant;
  else return { kind: "ignore", reason: `status ${status || "(none)"} not recognised` };

  const rawUser = body?.meta?.custom_data?.user_id;
  const userId = typeof rawUser === "string" && UUID.test(rawUser) ? rawUser.toLowerCase() : null;
  const email = typeof attrs.user_email === "string" && attrs.user_email.trim() ? attrs.user_email.trim().toLowerCase() : null;
  if (!userId && !email) return { kind: "ignore", reason: "no user id or email" };

  return {
    kind: "apply", plan, userId, email, subscriptionId: String(id), eventTime: new Date(updated).toISOString(),
    eventKey: await sha256Hex(`${name}:${id}:${updated}`), eventName: name, test,
  };
}



const json = (status: number, body: unknown) =>
  new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json" } });

// Projects on the new API keys get SUPABASE_SECRET_KEYS (JSON: name -> key); older ones get SUPABASE_SERVICE_ROLE_KEY.
function serviceKey(env: Record<string, string | undefined>): string | undefined {
  if (env.SUPABASE_SERVICE_ROLE_KEY) return env.SUPABASE_SERVICE_ROLE_KEY;
  try {
    const all = JSON.parse(env.SUPABASE_SECRET_KEYS || "{}");
    return all.default || Object.values(all).find((v) => typeof v === "string") as string | undefined;
  } catch { return undefined; }
}

// Takes the environment and fetch as arguments so it can be tested without Deno.
async function handleRequest(
  req: Request, env: Record<string, string | undefined>, fetchFn: typeof fetch,
): Promise<Response> {
  if (req.method !== "POST") return json(405, { ok: false, error: "POST only" });
  const secret = env.LS_WEBHOOK_SECRET;
  if (!secret) return json(500, { ok: false, error: "LS_WEBHOOK_SECRET is not set" });

  const raw = await req.text();
  if (!(await verifySignature(raw, req.headers.get("x-signature"), secret))) return json(401, { ok: false, error: "bad signature" });

  let body: unknown;
  try { body = JSON.parse(raw); } catch { return json(400, { ok: false, error: "bad json" }); }

  const cfg = parseConfig(env);
  if (!Object.keys(cfg.variants).length && !Object.keys(cfg.products).length) return json(500, { ok: false, error: "no LS_PRODUCT_* or LS_VARIANT_* set" });
  const d = await decide(body, cfg);
  if (d.kind === "ignore") return json(200, { ok: true, ignored: d.reason }); // 2xx so Lemon Squeezy does not retry

  const url = env.SUPABASE_URL, key = serviceKey(env);
  if (!url || !key) return json(500, { ok: false, error: "Supabase env missing" });
  // New-style sb_secret_ keys go in apikey only; legacy service_role JWTs also go in Authorization.
  const headers: Record<string, string> = { apikey: key, "content-type": "application/json" };
  if (!key.startsWith("sb_")) headers.authorization = `Bearer ${key}`;
  const r = await fetchFn(`${url}/rest/v1/rpc/apply_payment`, {
    method: "POST",
    headers,
    body: JSON.stringify({
      p_event_key: d.eventKey, p_event_name: d.eventName, p_user: d.userId, p_email: d.email, p_plan: d.plan,
      p_event_time: d.eventTime, p_subscription: d.subscriptionId, p_test: d.test,
    }),
  });
  if (!r.ok) return json(500, { ok: false, error: "database rejected the update" }); // non-2xx makes Lemon Squeezy retry
  const outcome = await r.json();
  return json(200, { ok: true, outcome, plan: d.plan });
}


// Supabase Edge Function: receives Lemon Squeezy webhooks and sets profiles.plan.
// Deploy with: supabase functions deploy lemon-webhook --no-verify-jwt   (see README.md)

Deno.serve((req: Request) => handleRequest(req, Deno.env.toObject(), fetch));
